import { test, expect } from '@playwright/test';

test.describe('Colour Contrast WCAG 2.1 AA Compliance', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should pass colour contrast checks for all elements', async ({ page }) => {
    // Locate and verify the main content container using getByRole
    const mainContainer = page.getByRole('main');
    await expect(mainContainer).toBeVisible();

    // Locate and verify navigation links using getByRole
    const navLinks = page.getByRole('navigation').locator('[data-testid="nav-link"]');
    await expect(navLinks).toHaveCount(3);

    // Locate and verify form elements using getByLabel
    const formInput = page.getByLabel('Email Address');
    await expect(formInput).toBeVisible();

    const formButton = page.getByRole('button', { name: /submit/i });
    await expect(formButton).toBeVisible();

    // Locate and verify error messages using getByRole
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();

    // Locate and verify success message using getByRole
    const successMessage = page.getByRole('alert');
    await expect(successMessage).not.toBeVisible();

    // Verify colour contrast using getByRole
    const contrastCheck = page.getByRole('heading', { name: /contrast check/i });
    await expect(contrastCheck).toBeVisible();

    // Verify contrast ratio using getByRole
    const contrastResult = page.getByRole('region', { name: /contrast ratio/i });
    await expect(contrastResult).toBeVisible();

    // Verify contrast ratio meets WCAG 2.1 AA standards
    const ratioValue = await contrastResult.evaluate((el) => {
      const contrastRatio = calculateContrastRatio(el);
      return contrastRatio >= 4.5 ? 'pass' : 'fail';
    });
    await expect(ratioValue).toBe('pass');

    // Verify all elements have appropriate colour contrast
    const allElements = page.locator('[data-testid="content-element"]');
    await expect(allElements).toHaveCount(10);
    const allPass = await allElements.evaluate((elements) => {
      return elements.every((el) => {
        const contrastRatio = calculateContrastRatio(el);
        return contrastRatio >= 4.5;
      });
    });
    await expect(allPass).toBe(true);
  });

  test('should fail colour contrast for specific elements', async ({ page }) => {
    // Locate and verify a button using getByRole
    const button = page.getByRole('button', { name: /submit/i });
    await expect(button).toBeVisible();

    // Manually set a low contrast colour for the button background
    await button.evaluate((el) => {
      el.style.backgroundColor = '#000000';
    });

    // Verify contrast ratio fails
    const contrastResult = page.getByRole('region', { name: /contrast ratio/i });
    await expect(contrastResult).toBeVisible();
    const ratioValue = await contrastResult.evaluate((el) => {
      const contrastRatio = calculateContrastRatio(el);
      return contrastRatio >= 4.5 ? 'pass' : 'fail';
    });
    await expect(ratioValue).toBe('fail');

    // Verify error message is displayed
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();

    // Verify contrast ratio is displayed
    const contrastResultText = page.getByText(/contrast ratio: 1.00/i);
    await expect(contrastResultText).toBeVisible();

    // Verify button is still visible
    await expect(button).toBeVisible();
  });
});
